Section FREE.
Hypothesis NTF : NTF_SPEC.

Theorem free_INVL st L BL LS c off n :
  INVL x0 st L BL LS -> In ((c, off), n) BL ->
  ftree L (free st (Some (aadd c (UNIT * off))))
